import React from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";
import { useDispatch } from "react-redux";
import { useEffect } from "react";
import { setAuthToken } from "./redux/root/api";
import { loadFromStorage } from "./redux/auth/authSlice";
import ProductForm from "./components/product/ProductForm";
import ProductList from "./components/product/ProductList";
import EmployeeForm from "./components/employee/EmployeeForm";
import EmployeeList from "./components/employee/EmployeeList";
import UserForm from "./components/user/UserForm";
import UserList from "./components/user/UserList";
import Layout from "./components/layout";
import Login from "./components/login/Login";
import Signup from "./components/login/Signup"; // کامپوننت جدید برای ثبت نام
import ProtectedRoute from "./components/login/ProtectedRoute";
import AdminRoute from "./components/login/AdminRoute";

function App() {
  const dispatch = useDispatch();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      setAuthToken(token);
      dispatch(loadFromStorage());
    }
  }, [dispatch]);

  return (
    <Router>
      <Routes>
        {/* صفحه اصلی - ریدایرکت به لاگین اگر توکن وجود ندارد */}
        <Route
          path="/"
          element={
            localStorage.getItem("token") ? (
              <ProtectedRoute>
                <Layout>
                  <EmployeeList />
                </Layout>
              </ProtectedRoute>
            ) : (
              <Navigate to="/login" replace />
            )
          }
        />

        {/* صفحات عمومی بدون نیاز به لاگین */}
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />

        {/* صفحات محافظت شده */}
        <Route
          path="/add"
          element={
            <ProtectedRoute>
              <Layout>
                <EmployeeForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/edit/:id"
          element={
            <ProtectedRoute>
              <Layout>
                <EmployeeForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/products"
          element={
            <ProtectedRoute>
              <Layout>
                <ProductList />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/products/add"
          element={
            <ProtectedRoute>
              <Layout>
                <ProductForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        {/* صفحات مدیریت کاربران (فقط برای ادمین) */}
        <Route
          path="/users"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserList />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/add"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/edit/:id"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        {/* ریدایرکت برای صفحات ناشناخته */}
        <Route path="*" element={<Navigate to="/login" replace />} />
      </Routes>
    </Router>
  );
}

export default App;
